310:         <span class="art-word" aria-hidden="true">${event.artWord}</span>
311:       </div>
312:       <div class="event-body">
313:         <div class="event-meta">
314:           <span>${ICONS.clock}${event.time}</span>
315:           <span>${ICONS.pin}${event.venueShort}</span>
316:         </div>
317:         <h3>${escapeHTML(event.title)}</h3>
318:         <p class="event-desc">${escapeHTML(event.tagline)}</p>
319:         <div class="seats${isLow ? " is-low" : ""}">
320:           <div class="seats-meta">
321:             <span class="seats-left">${isFull ? "Fully booked" : `${left} seat${left === 1 ? "" : "s"} left`}</span>
322:             <span>${event.capacity} total</span>
323:           </div>
324:           <div class="seat-bar" role="img" aria-label="${percent}% of seats remaining">
325:             <span style="width:${percent}%"></span>
326:           </div>
327:         </div>
328:         <div class="event-actions">
329:           <button class="btn btn-outline" type="button" data-action="details" data-event="${event.id}">Details</button>
330:           <button class="btn btn-dark" type="button" data-action="register" data-event="${event.id}"${isFull ? " disabled" : ""}>${isFull ? "Full" : "Register"}</button>
331:         </div>
332:       </div>
333:     </article>
334:   `;
335: }
