360:   const current = select.value;
361:   const days = [
362:     { key: "day1", label: "Wednesday 18 November" },
363:     { key: "day2", label: "Thursday 19 November" },
364:     { key: "day3", label: "Friday 20 November" },
365:     { key: "day4", label: "Saturday 21 November" }
366:   ];
367: 
368:   let options = '<option value="">Select an event</option>';
369:   days.forEach((day) => {
370:     const dayEvents = EVENTS.filter((event) => event.dayKey === day.key);
371:     options += `<optgroup label="${day.label}">`;
372:     dayEvents.forEach((event) => {
373:       const left = seatsLeft(event);
374:       options += `<option value="${event.id}"${left === 0 ? " disabled" : ""}>${escapeHTML(event.title)} — ${event.time}${left === 0 ? " (full)" : ` · ${left} left`}</option>`;
375:     });
376:     options += "</optgroup>";
377:   });
378: 
379:   select.innerHTML = options;
380:   if (current && getEvent(current) && seatsLeft(getEvent(current)) > 0) {
381:     select.value = current;
382:   }
383: }
