385: function renderSchedule() {
386:   Object.keys(SCHEDULE).forEach((day) => {
387:     const panel = document.querySelector(`[data-panel="${day}"]`);
388:     if (!panel) return;
389: 
390:     panel.innerHTML = SCHEDULE[day]
391:       .map(
392:         (session) => `
393:           <article class="session">
394:             <div class="session-time">
395:               <strong>${session.time}</strong>
396:               <span>${session.period}</span>
397:             </div>
398:             <div class="session-info">
399:               <h3>${escapeHTML(session.title)}</h3>
400:               <p>${escapeHTML(session.meta)}</p>
401:             </div>
402:             <div class="session-tags">
403:               <span class="tag">${escapeHTML(session.tag)}</span>
404:               ${session.flagship ? '<span class="tag tag-flag">Flagship</span>' : ""}
405:             </div>
406:           </article>
407:         `
408:       )
409:       .join("");
410:   });
411: }
412: 
413: function setupScheduleTabs() {
414:   const tabs = $$(".day-tab");
415: 
416:   const activate = (day, moveFocus = false) => {
417:     tabs.forEach((tab) => {
418:       const active = tab.dataset.day === day;
419:       tab.classList.toggle("is-active", active);
420:       tab.setAttribute("aria-selected", active ? "true" : "false");
421:       tab.tabIndex = active ? 0 : -1;
422: 
423:       const panel = document.querySelector(`[data-panel="${tab.dataset.day}"]`);
424:       if (panel) {
425:         panel.hidden = !active;
426:         panel.classList.toggle("is-active", active);
427:       }
428: 
429:       if (active && moveFocus) tab.focus();
430:     });
431:   };
432: 
433:   tabs.forEach((tab, index) => {
434:     tab.addEventListener("click", () => activate(tab.dataset.day));
435: 
436:     tab.addEventListener("keydown", (event) => {
437:       let nextIndex = null;
438:       if (event.key === "ArrowRight") nextIndex = (index + 1) % tabs.length;
439:       if (event.key === "ArrowLeft") nextIndex = (index - 1 + tabs.length) % tabs.length;
440:       if (event.key === "Home") nextIndex = 0;
441:       if (event.key === "End") nextIndex = tabs.length - 1;
442: 
443:       if (nextIndex !== null) {
444:         event.preventDefault();
445:         activate(tabs[nextIndex].dataset.day, true);
446:       }
447:     });
448:   });
449: }
450: 
451: /* ------------------------------------------------------------
452:    6. Countdown
453:    ------------------------------------------------------------ */
454: function updateCountdown() {
455:   const countdown = $("#countdown");
456:   if (!countdown) return;
457: 
458:   const difference = EVENT_START - Date.now();
459: 
460:   if (difference <= 0) {
461:     countdown.classList.add("is-live");
462:     countdown.innerHTML = '<p class="countdown-live">CampusFest is live — see you there!</p>';
463:     return;
464:   }
465: 
466:   const days = Math.floor(difference / 86400000);
467:   const hours = Math.floor((difference % 86400000) / 3600000);
468:   const minutes = Math.floor((difference % 3600000) / 60000);
469:   const seconds = Math.floor((difference % 60000) / 1000);
470: 
471:   const values = { days, hours, minutes, seconds };
472:   Object.keys(values).forEach((unit) => {
473:     const element = countdown.querySelector(`[data-unit="${unit}"]`);
474:     if (element) element.textContent = pad(values[unit]);
475:   });
476: }
