514:         ${isFull ? "Fully booked" : "Reserve my seat"}
515:         ${isFull ? "" : '<svg viewBox="0 0 20 20" fill="none" aria-hidden="true"><path d="M4 10h12M11 5l5 5-5 5" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>'}
