541:    8. Form validation & submission
542:    ------------------------------------------------------------ */
543: const fieldMap = {
544:   fullName: { input: $("#fullName"), error: $("#fullNameError") },
545:   studentId: { input: $("#studentId"), error: $("#studentIdError") },
546:   email: { input: $("#email"), error: $("#emailError") },
547:   phone: { input: $("#phone"), error: $("#phoneError") },
548:   year: { input: $("#year"), error: $("#yearError") },
549:   eventId: { input: $("#eventSelect"), error: $("#eventSelectError") },
550:   terms: { input: $("#terms"), error: $("#termsError") }
551: };
552: 
553: const validators = {
554:   fullName: (value) =>
555:     value.trim().length >= 2 ? "" : "Please enter your full name (at least 2 characters).",
556:   studentId: (value) =>
557:     /^[A-Za-z0-9-]{4,20}$/.test(value.trim())
558:       ? ""
559:       : "Use 4–20 letters, numbers or hyphens (e.g. NF22CS104).",
560:   email: (value) =>
561:     /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(value.trim())
562:       ? ""
