  const ALIASES = {
    codestorm: ["codestorm", "code storm", "hackathon", "code storm hackathon"],
    "neon-nights": ["neon nights", "neon", "cultural fest", "cultural night"],
    "hoops-3v3": ["hoops", "hoops 3v3", "3v3", "3 on 3", "basketball"],
