  function festWhen() {
    botSay(
      `<p>CampusFest '26 runs <strong>Wednesday 18 to Saturday 21 November 2026</strong>. Events start as early as 6:30 AM for the Campus Run and finish with the closing ceremony on Saturday night.</p>`,
      { quick: ["Browse all events", "Help me choose"] }
    );
  }

  function festWhere() {
    botSay(
      `<p>Everything happens on the <strong>Northfield College campus</strong>. Venues range from the Innovation Lab and Main Auditorium to the Indoor Courts, Campus Lake and Open Air Stage — each event card lists its exact venue.</p>`,
      { quick: ["Browse all events", "Help me choose"] }
