  /* ----------------------------------------------------------
     Conversation router
     ---------------------------------------------------------- */
  function respond(raw) {
    const text = normalize(raw);

    if (!text) return;

    if (/^(hi|hey|hello|yo|hola|namaste|good morning|good afternoon|good evening)\b/.test(text)) {
      botSay(
        `<p>Hey! I am the CampusFest guide. Tell me what you are into and I will find the right event — or ask me anything about the line-up.</p>`,
        { quick: PREFERENCE_QUICK }
      );
      return;
    }

    if (/^(thanks|thank you|thx|cheers|perfect|great|awesome|cool)\b/.test(text)) {
      botSay(`<p>Anytime. Want another suggestion, or help with registration?</p>`, {
        quick: ["Help me choose", "How do I register?", "Browse all events"]
      });
      return;
    }

    if (/^(bye|goodbye|see you|thats all|that is all)\b/.test(text)) {
      botSay(`<p>See you at CampusFest — 18 to 21 November. Have a great fest!</p>`, { quick: [] });
      return;
    }

    if (/\b(surprise me|wildcard|random)\b/.test(text)) {
      surprisePick();
      return;
    }

    const event = findEvent(text);
    if (event) {
      const aspect = detectAspect(text);
      const asksHow = /\b(how|where|help|explain)\b/.test(text);
      if (aspect === "register" && !asksHow) {
        startRegistration(event);
        return;
      }
      botSay(eventAnswer(event, aspect), { quick: DEFAULT_QUICK });
      return;
    }

    if (ALT_INTENT.test(text)) {
      alternatives();
      return;
    }

    if (RECOMMEND_INTENT.test(text)) {
      const scored = scoreEvents(text);
      if (scored.length) recommend(scored);
      else askPreferences();
      return;
    }

    if (SCHEDULE_INTENT.test(text)) {
      scheduleAnswer();
      return;
    }

    if (LIST_INTENT.test(text)) {
      botSay(`<p>Here is the full line-up. Tap any event for the details, or ask me to narrow it down.</p>${listEventsHTML()}`, {
        quick: ["Help me choose", "How do I register?"]
      });
      return;
    }

    if (FREE_INTENT.test(text)) {
      freeAnswer();
      return;
    }

    if (REGISTER_INTENT.test(text)) {
      if (lastPick && /\b(it|that|this|one)\b/.test(text)) {
        const picked = findById(lastPick);
        if (picked) {
          startRegistration(picked);
          return;
        }
      }
      howToRegister();
      return;
    }

    if (TEAM_INTENT.test(text)) {
      teamAnswer();
      return;
    }

    if (FOOD_INTENT.test(text)) {
      foodAnswer();
      return;
    }

    if (CONTACT_INTENT.test(text)) {
      contactAnswer();
      return;
    }

    if (/\b(fest|festival|campusfest)\b/.test(text) && /\b(when|date|dates|what day|how long|start|end)\b/.test(text)) {
      festWhen();
      return;
    }

    if (/\b(fest|festival|campusfest)\b/.test(text) && /\b(where|venue|location|campus)\b/.test(text)) {
      festWhere();
      return;
    }

    if (CAPABILITY_INTENT.test(text)) {
      capabilities();
      return;
    }

    if (lastPick) {
      const picked = findById(lastPick);
      const refers = /\b(it|that|this|this one|that one|the event)\b/.test(text);
      const aspect = detectAspect(text);
      if (picked && (refers || ["when", "where", "seats", "bring", "who", "team", "cost"].includes(aspect))) {
        botSay(eventAnswer(picked, aspect), { quick: DEFAULT_QUICK });
        return;
      }
    }

    const scored = scoreEvents(text);
    if (scored.length) {
      recommend(scored);
      return;
    }

    fallback();
  }

  /* ----------------------------------------------------------
     Open / close & events
     ---------------------------------------------------------- */
  function openChat() {
    if (isOpen) {
      input.focus({ preventScroll: true });
      return;
    }

    isOpen = true;
    panel.hidden = false;
    launcher.setAttribute("aria-expanded", "true");
    window.requestAnimationFrame(() => panel.classList.add("is-open"));

    if (!hasGreeted) {
      hasGreeted = true;
      botSay(
        `<p><strong>Hey — I am the CampusFest guide.</strong> Tell me what you are into and I will find the right event, or ask me anything about the line-up.</p>`,
        { quick: PREFERENCE_QUICK, delay: 550 }
      );
    }

    window.setTimeout(() => input.focus({ preventScroll: true }), 260);
  }

  function closeChat() {
    if (!isOpen) return;
    isOpen = false;
    panel.classList.remove("is-open");
    launcher.setAttribute("aria-expanded", "false");

    const finish = () => {
      if (!isOpen) panel.hidden = true;
    };

    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) finish();
    else window.setTimeout(finish, 240);

    launcher.focus({ preventScroll: true });
  }

  function goToSection(selector) {
    const target = document.querySelector(selector);
    if (!target) return;
    closeChat();
    window.setTimeout(() => target.scrollIntoView({ behavior: "smooth", block: "start" }), 220);
  }

  launcher.addEventListener("click", () => (isOpen ? closeChat() : openChat()));
  openers.forEach((opener) => opener.addEventListener("click", openChat));

  if (closeButton) closeButton.addEventListener("click", closeChat);

  form.addEventListener("submit", (event) => {
    event.preventDefault();
    submitMessage(input.value);
  });

  document.addEventListener("keydown", (event) => {
    if (event.key === "Escape" && isOpen) closeChat();
  });

  log.addEventListener("click", (event) => {
    const detailsButton = event.target.closest("[data-chat-details]");
    if (detailsButton) {
      const eventId = detailsButton.getAttribute("data-chat-details");
      const selected = findById(eventId);
      if (selected && typeof openEventDialog === "function") {
        openEventDialog(selected);
      }
      return;
    }

    const registerButton = event.target.closest("[data-chat-register]");
    if (registerButton) {
      const eventId = registerButton.getAttribute("data-chat-register");
      const selected = findById(eventId);
      if (selected) startRegistration(selected);
      return;
    }

    const scrollButton = event.target.closest("[data-chat-scroll]");
    if (scrollButton) {
      goToSection(scrollButton.getAttribute("data-chat-scroll"));
    }
  });

  /* Greeting is created on first open so the panel is never empty. */
  setQuickReplies([]);
})();

/* ============================================================
   CampusFest '26 — festival guide chat assistant
   ============================================================ */

.chatbot {
  --chat-width: 400px;
}

/* ---------- Launcher ---------- */
.chat-launcher {
  position: fixed;
  right: 24px;
  bottom: 24px;
  z-index: 160;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 9px 16px 9px 9px;
  border: 1px solid var(--ink);
  border-radius: 999px;
  background: var(--ink);
  color: var(--paper);
  text-align: left;
  box-shadow: 0 18px 45px -18px rgba(21, 22, 15, 0.7);
  transition: transform 0.2s ease, background-color 0.2s ease, box-shadow 0.2s ease;
}

.chat-launcher:hover {
  transform: translateY(-2px);
  background: var(--ink-soft);
  box-shadow: 0 22px 52px -18px rgba(21, 22, 15, 0.75);
}

.chat-launcher-icon {
  width: 36px;
  height: 36px;
  display: grid;
  place-items: center;
  flex-shrink: 0;
  border-radius: 50%;
  background: var(--lime);
  color: var(--ink);
}

.chat-launcher-icon svg {
  width: 18px;
  height: 18px;
}

.chat-launcher-text strong {
  display: block;
  font-size: 0.78rem;
  font-weight: 600;
  line-height: 1.2;
}

.chat-launcher-text small {
  display: block;
  margin-top: 2px;
  font-size: 0.62rem;
  color: rgba(243, 239, 228, 0.62);
}

.chat-launcher-badge {
  padding: 3px 7px;
  border-radius: 999px;
  background: var(--lime);
  color: var(--ink);
  font-size: 0.55rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

/* ---------- Panel ---------- */
.chat-panel {
  position: fixed;
  right: 24px;
  bottom: 96px;
  z-index: 161;
  width: min(var(--chat-width), calc(100vw - 32px));
  height: min(620px, calc(100dvh - 128px));
  display: flex;
  flex-direction: column;
  overflow: hidden;
  background: var(--paper);
  border: 1px solid var(--ink);
  border-radius: 22px;
  box-shadow: 0 40px 90px -30px rgba(21, 22, 15, 0.55);
  opacity: 0;
  transform: translateY(16px) scale(0.98);
  transition: opacity 0.22s ease, transform 0.22s ease;
}

.chat-panel.is-open {
  opacity: 1;
  transform: none;
}

.chat-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 13px 14px;
  background: var(--ink);
  color: var(--paper);
  border-bottom: 1px solid rgba(243, 239, 228, 0.14);
}

.chat-identity {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
}

.chat-avatar {
  width: 38px;
  height: 38px;
  display: grid;
  place-items: center;
  flex-shrink: 0;
  border-radius: 50%;
  background: var(--lime);
  color: var(--ink);
}

.chat-avatar svg {
  width: 20px;
  height: 20px;
}

.chat-identity strong {
  display: block;
  font-size: 0.84rem;
  font-weight: 600;
  letter-spacing: 0.01em;
}

.chat-identity span {
  display: flex;
  align-items: center;
  gap: 5px;
  margin-top: 2px;
  font-size: 0.62rem;
  color: rgba(243, 239, 228, 0.65);
}

.chat-status-dot {
  width: 6px;
  height: 6px;
  flex-shrink: 0;
  border-radius: 50%;
  background: var(--lime);
  box-shadow: 0 0 0 2px rgba(201, 242, 74, 0.22);
}

.chat-close {
  width: 32px;
  height: 32px;
  display: grid;
  place-items: center;
  flex-shrink: 0;
  border: 1px solid rgba(243, 239, 228, 0.22);
  border-radius: 8px;
  background: transparent;
  color: var(--paper);
  transition: background-color 0.15s ease, color 0.15s ease;
}

.chat-close:hover {
  background: var(--lime);
  color: var(--ink);
}

.chat-close svg {
  width: 14px;
  height: 14px;
}

/* ---------- Conversation ---------- */
.chat-log {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 10px;
  overflow-y: auto;
  overscroll-behavior: contain;
  padding: 16px 14px 10px;
  background-color: var(--paper);
  background-image: radial-gradient(rgba(21, 22, 15, 0.05) 1px, transparent 1px);
  background-size: 15px 15px;
  scrollbar-width: thin;
}

.chat-msg {
  max-width: 88%;
  font-size: 0.82rem;
  line-height: 1.55;
  overflow-wrap: anywhere;
}

.chat-msg p {
  margin: 0 0 8px;
}

.chat-msg p:last-child {
  margin-bottom: 0;
}

.chat-msg--bot {
  align-self: flex-start;
  padding: 10px 12px;
  border: 1px solid var(--line);
  border-radius: 4px 14px 14px 14px;
  background: var(--white);
  box-shadow: 0 8px 18px -16px rgba(21, 22, 15, 0.55);
}

.chat-msg--user {
  align-self: flex-end;
  padding: 9px 12px;
  border-radius: 14px 4px 14px 14px;
  background: var(--ink);
  color: var(--paper);
}

.chat-msg--user p {
  margin: 0;
}

.chat-msg em {
  font-style: normal;
  font-weight: 600;
  border-bottom: 2px solid var(--lime);
}

.chat-msg a {
  color: inherit;
  text-decoration-color: var(--lime-deep);
  text-underline-offset: 3px;
}

/* ---------- Typing ---------- */
.chat-typing {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 12px 14px;
}

.chat-typing span {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--muted);
  animation: chat-bounce 1s infinite ease-in-out;
}

.chat-typing span:nth-child(2) {
  animation-delay: 0.12s;
}

.chat-typing span:nth-child(3) {
  animation-delay: 0.24s;
}

@keyframes chat-bounce {
  0%,
  60%,
  100% {
    transform: translateY(0);
    opacity: 0.45;
  }
  30% {
    transform: translateY(-3px);
    opacity: 1;
  }
}

/* ---------- Rich answers ---------- */
.chat-event {
  margin-top: 10px;
  padding: 11px;
  border: 1px solid var(--line-strong);
  border-radius: 12px;
  background: var(--paper);
}

.chat-event-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 5px;
}

.chat-event-cat {
  font-size: 0.54rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--muted);
}

.chat-event-seats {
  padding: 2px 7px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: var(--white);
  color: var(--muted);
  font-size: 0.56rem;
  font-weight: 700;
  white-space: nowrap;
}

.chat-event-seats.is-low {
  border-color: transparent;
  background: var(--coral-soft);
  color: var(--coral-ink);
}

.chat-event > strong {
  display: block;
  margin-bottom: 3px;
  font-size: 0.9rem;
  line-height: 1.25;
}

.chat-event > p {
  margin: 0 0 8px;
  color: var(--muted);
  font-size: 0.73rem;
  line-height: 1.45;
}

.chat-facts {
  display: grid;
  gap: 4px;
  margin: 0 0 10px;
}

.chat-facts div {
  display: flex;
  gap: 8px;
  font-size: 0.69rem;
  line-height: 1.35;
}

.chat-facts dt {
  min-width: 42px;
  color: var(--muted);
  font-weight: 600;
}

.chat-facts dd {
  margin: 0;
  color: var(--ink);
}

.chat-event-actions {
  display: flex;
  gap: 6px;
}

.chat-event-actions button {
  flex: 1;
  padding: 7px 10px;
  border: 1px solid var(--ink);
  border-radius: 8px;
  background: var(--white);
  color: var(--ink);
  font: inherit;
  font-size: 0.68rem;
  font-weight: 600;
  transition: background-color 0.15s ease, color 0.15s ease;
}

.chat-event-actions button:hover {
  background: var(--lime);
}

.chat-event-actions button.is-primary {
  background: var(--ink);
  color: var(--paper);
}

.chat-event-actions button.is-primary:hover {
  background: var(--lime);
  color: var(--ink);
}

.chat-event-actions button:disabled {
  cursor: not-allowed;
  opacity: 0.4;
}

.chat-alt-label {
  margin-top: 10px !important;
  color: var(--muted);
  font-size: 0.68rem !important;
}

.chat-alt-list {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
}

.chat-alt-list button {
  padding: 5px 9px;
  border: 1px solid var(--line-strong);
  border-radius: 999px;
  background: var(--white);
  color: var(--ink);
  font: inherit;
  font-size: 0.66rem;
  font-weight: 500;
  transition: background-color 0.15s ease, border-color 0.15s ease;
}

.chat-alt-list button:hover {
  border-color: var(--ink);
  background: var(--lime-soft);
}

/* ---------- Lists ---------- */
.chat-list {
  display: grid;
  gap: 5px;
  margin: 8px 0 0;
  padding: 0;
  list-style: none;
}

.chat-list button {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  width: 100%;
  padding: 8px 10px;
  border: 1px solid var(--line);
  border-radius: 9px;
  background: var(--white);
  color: var(--ink);
  font: inherit;
  text-align: left;
  transition: background-color 0.15s ease, border-color 0.15s ease;
}

.chat-list button:hover {
  border-color: var(--ink);
  background: var(--lime-soft);
}

.chat-list strong {
  display: block;
  font-size: 0.72rem;
  font-weight: 600;
  line-height: 1.25;
}

.chat-list small {
  display: block;
  margin-top: 1px;
  color: var(--muted);
  font-size: 0.6rem;
  line-height: 1.3;
}

.chat-list-seats {
  flex-shrink: 0;
  color: var(--muted);
  font-size: 0.57rem;
  font-weight: 700;
  white-space: nowrap;
}

.chat-steps,
.chat-bullets {
  margin: 6px 0 8px;
  padding-left: 17px;
  font-size: 0.77rem;
}

.chat-steps li,
.chat-bullets li {
  margin-bottom: 3px;
}

.chat-wide-btn {
  display: block;
  width: 100%;
  padding: 8px;
  border: 1px solid var(--ink);
  border-radius: 8px;
  background: var(--lime);
  color: var(--ink);
  font: inherit;
  font-size: 0.72rem;
  font-weight: 600;
  transition: background-color 0.15s ease;
}

.chat-wide-btn:hover {
  background: var(--lime-soft);
}

/* ---------- Schedule ---------- */
.chat-schedule {
  display: grid;
  gap: 9px;
  margin-top: 8px;
}

.chat-schedule h4 {
  margin: 0 0 3px;
  color: var(--muted);
  font-size: 0.58rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.chat-schedule ul {
  display: grid;
  gap: 2px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.chat-schedule li {
  display: flex;
  gap: 7px;
  font-size: 0.69rem;
  line-height: 1.35;
}

.chat-schedule li span {
  min-width: 56px;
  flex-shrink: 0;
  color: var(--muted);
  font-variant-numeric: tabular-nums;
}

/* ---------- Quick replies & composer ---------- */
.chat-quick {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  max-height: 106px;
  overflow-y: auto;
  padding: 8px 12px;
  border-top: 1px solid var(--line);
  background: var(--paper);
}

.chat-chip {
  padding: 5px 10px;
  border: 1px solid var(--line-strong);
  border-radius: 999px;
  background: var(--white);
  color: var(--ink);
  font: inherit;
  font-size: 0.66rem;
  font-weight: 500;
  transition: background-color 0.15s ease, border-color 0.15s ease;
}

.chat-chip:hover {
  border-color: var(--ink);
  background: var(--lime);
}

.chat-form {
  display: flex;
  gap: 6px;
  padding: 9px 12px;
  border-top: 1px solid var(--line);
  background: var(--white);
}

.chat-form input {
  flex: 1;
  min-width: 0;
  padding: 9px 11px;
  border: 1px solid var(--line-strong);
  border-radius: 10px;
  background: var(--paper);
  color: var(--ink);
  font: inherit;
  font-size: 0.78rem;
}

.chat-form input::placeholder {
  color: var(--muted);
}

.chat-form input:focus {
  outline: 2px solid var(--ink);
  outline-offset: 1px;
}

.chat-send {
  width: 38px;
  height: 38px;
  display: grid;
  place-items: center;
  flex-shrink: 0;
  border: 1px solid var(--ink);
  border-radius: 10px;
  background: var(--ink);
  color: var(--paper);
  transition: background-color 0.15s ease, color 0.15s ease;
}

.chat-send:hover {
  background: var(--lime);
  color: var(--ink);
}

.chat-send svg {
  width: 16px;
  height: 16px;
}

.chat-foot {
  margin: 0;
  padding: 6px 12px 8px;
  background: var(--white);
  color: var(--muted);
  font-size: 0.55rem;
  text-align: center;
}

/* ---------- Hero entry point ---------- */
.hero-guide {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  margin-top: 14px;
  padding: 4px 2px;
  border: 0;
  background: none;
  color: var(--muted);
  font: inherit;
  font-size: 0.78rem;
  text-align: left;
}

.hero-guide strong {
  color: var(--ink);
  font-weight: 600;
  text-decoration: underline;
  text-decoration-color: var(--lime-deep);
  text-decoration-thickness: 2px;
  text-underline-offset: 3px;
}

.hero-guide:hover {
  color: var(--ink);
}

.hero-guide-spark {
  width: 20px;
  height: 20px;
  display: grid;
  place-items: center;
  flex-shrink: 0;
  border-radius: 50%;
  background: var(--lime);
  color: var(--ink);
}

.hero-guide-spark svg {
  width: 12px;
  height: 12px;
}

/* ---------- Responsive ---------- */
@media (max-width: 640px) {
  .chat-launcher {
    right: 14px;
    bottom: 14px;
    gap: 0;
    padding: 8px;
    border-radius: 50%;
  }

  .chat-launcher-text,
  .chat-launcher-badge {
    display: none;
  }

  .chat-launcher-icon {
    width: 42px;
    height: 42px;
  }

  .chat-panel {
    right: 10px;
    left: 10px;
    bottom: 76px;
    width: auto;
    height: min(78dvh, 620px);
    border-radius: 18px;
  }

  .chat-head {
    padding: 12px 14px;
  }

  .chat-log {
    padding: 12px 10px 8px;
  }

  .chat-msg {
    max-width: 94%;
  }

  .chat-foot {
    font-size: 0.52rem;
  }
}

@media (max-height: 560px) {
  .chat-panel {
    bottom: 76px;
    height: calc(100dvh - 90px);
  }
}

@media (prefers-reduced-motion: reduce) {
  .chat-panel,
  .chat-launcher {
    transition: none;
  }

  .chat-panel {
    transform: none;
  }

  .chat-typing span {
    animation: none;
  }
}

@media print {
  .chatbot {
    display: none !important;
  }
}

