content.text:
Now create test harness. It should not be left in final project. We'll delete after.

Harness script:

```html
<!doctype html>
<html><body>
<iframe id="frame" src="/index.html" style="width:1200px;height:900px"></iframe>
<pre id="results">pending</pre>
<script>
const results = [];
function record(name, value) { results.push({name, ...value}); }
const frame = document.getElementById('frame');
frame.addEventListener('load', () => {
  const doc = frame.contentDocument;
  const win = frame.contentWindow;
  const errors = [];
  win.addEventListener('error', e => errors.push(String(e.message)));
  const wait = ms => new Promise(r => setTimeout(r, ms));
  async function ask(text) {
    const input = doc.getElementById('chatInput');
    input.value = text;
    doc.getElementById('chatForm').dispatchEvent(new win.Event('submit', {bubbles:true, cancelable:true}));
    await wait(700);
    const msgs = [...doc.querySelectorAll('.chat-msg--bot')];
    return msgs[msgs.length-1].innerText.slice(0, 300);
  }
  (async () => {
    await wait(300);
    const launcher = doc.getElementById('chatLauncher');
    record('launcherExists', {ok: !!launcher});
    launcher.click();
    await wait(900);
    record('panelOpen', {ok: !doc.getElementById('chatPanel').hidden});
    record('greeting', {text: doc.querySelector('.chat-msg--bot')?.innerText.slice(0,80)});
    record('quickCount', {count: doc.querySelectorAll('.chat-chip').length});
    const tests = {};
    tests.hello = await ask('hello');
    tests.coding = await ask('I like coding and music');
    // check event card
    record('recommendCard', {title: doc.querySelector('.chat-msg--bot:last-child .chat-event strong')?.innerText, alt: ...});
    tests.when = await ask('when is it');
    tests.hackathon = await ask('when is CodeStorm?');
    tests.seats = await ask('how many seats are left for hoops?');
    tests.free = await ask('is it free?');
    tests.registerHow = await ask('how do I register?');
    tests.team = await ask('do I need a team?');
    tests.schedule = await ask('show me the schedule');
    tests.fallback = await ask('do you have a bus?');
    // test details button opens dialog
    const details = doc.querySelector('[data-chat-details]');
    if (details) { details.click(); await wait(300); record('dialogOpened', {ok: doc.getElementById('eventDialog').open}); doc.getElementById('dialogClose').click(); }
    // test registration integration: ask coding then click register button
    await ask('help me choose tech');
    const regBtn = doc.querySelector('.chat-msg--bot:last-child [data-chat-register]');
    if (regBtn) { regBtn.click(); await wait(1600); record('registerSelect', {value: doc.getElementById('eventSelect').value, panelHidden: doc.getElementById('chatPanel').hidden}); }
    record('errors', {errors});
    record('samples', tests);
    document.getElementById('results').textContent = JSON.stringify(results, null, 2);
    document.title = 'DONE';
  })();
});
</script>
</body></html>
```

Issue: app.js and chatbot.js in iframe load. `win.Event` for submit. `form.dispatchEvent` triggers listener. Good.

But multiple awaits with real-time; Chrome `--virtual-time-budget` may accelerate timers. With 700ms waits repeated ~10 = ~8s. Use budget 30000.

Need ensure iframe load fires; yes.

`innerText` in headless dump maybe works.

Also we can test keyboard Escape closes.

Record dialog open: native `<dialog>.open`.

Registration flow: after clicking register, `startRegistration` botSay delay 420 then after callback schedules 550 close -> total ~1s. chooseEvent occurs. Wait 1600.

However, when details dialog opens, `openEventDialog` calls showModal. Then close button click. Good.

One catch: asking "help me choose tech" triggers RECOMMEND_INTENT, scoreEvents finds "tech" → code storm. Good.

