  display: inline-flex;
  align-items: center;
  gap: 11px;
  text-decoration: none;
  flex-shrink: 0;
}

.brand-mark {
  width: 42px;
  height: 42px;
  display: grid;
  place-items: center;
  border-radius: 12px;
  background: var(--ink);
  color: var(--lime);
  border: 1.5px solid var(--ink);
}

.brand-mark svg {
  width: 24px;
  height: 24px;
}

